import {
  Column,
  CreateDateColumn,
  Entity,
  PrimaryColumn,
  Unique,
  UpdateDateColumn,
} from 'typeorm';
import { UserRole, UserStatus } from '../domain/user.js';

@Entity('users')
@Unique('UQ_users_email', ['email'])
export class UserOrmEntity {
  // The id is generated by the domain (User.registerResearcher).
  @PrimaryColumn('uuid', { primaryKeyConstraintName: 'PK_users_id' })
  id: string;

  @Column({ name: 'full_name', length: 150 })
  fullName: string;

  @Column({ length: 254 })
  email: string;

  @Column({ name: 'password_hash', length: 100 })
  passwordHash: string;

  @Column({ length: 200 })
  institution: string;

  @Column({ name: 'request_reason', type: 'text', nullable: true })
  requestReason: string | null;

  @Column({ type: 'enum', enum: UserRole, enumName: 'user_role_enum' })
  role: UserRole;

  @Column({ type: 'enum', enum: UserStatus, enumName: 'user_status_enum' })
  status: UserStatus;

  @Column({ name: 'rejection_reason', type: 'text', nullable: true })
  rejectionReason: string | null;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt: Date;

  @UpdateDateColumn({ name: 'updated_at', type: 'timestamptz' })
  updatedAt: Date;
}
